src/app.controller.spec.ts
</FILEPATH>
<CODE>
import { Test, TestingModule } from '@nestjs/testing';
import { AppController } from './app.controller';
import { AppService } from './app.service';

describe('AppController', () => {
  let appController: AppController;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [AppService],
    }).compile();

    appController = module.get<AppController>(AppController);
  });

  describe('calculate', () => {
    it('should return the result of the expression', () => {
      const result = appController.calculate({ expression: '1 + 2 * 3' });
      expect(result).toEqual({ result: '7' });
    });

    it('should throw an error for invalid expression', () => {
      expect(() => appController.calculate({ expression: 'invalid' })).toThrow();
    });
  });
});
</CODE>

<FILEPATH>
src/app.controller.ts
</FILEPATH>
<CODE>
import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { AppService } from './app.service';

@Controller('calculator')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post()
  calculate(@Body() body: { expression: string }): { result: string } {
    try {
      const result = this.appService.calculateExpression(body.expression);
      return { result: result.toString() };
    } catch (error) {
      throw new HttpException('Invalid input', HttpStatus.BAD_REQUEST);
    }
  }
}
</CODE>

<FILEPATH>
src/app.module.ts
</FILEPATH>
<CODE>
import { Module } from '@nestjs/common';
import { AppController } from './app.controller';
import { AppService } from './app.service';

@Module({
  imports: [],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}
</CODE>

<FILEPATH>
src/app.service.ts
</FILEPATH>
<CODE>
import { Injectable } from '@nestjs/common';

@Injectable()
export class AppService {
  calculateExpression(expression: string): number {
    // A simple parser for arithmetic expressions
    const sanitizedExpression = expression.replace(/[^0-9+\-*/(). ]/g, '');
    return this.evaluate(sanitizedExpression);
  }

  private evaluate(expr: string): number {
    // Use Function constructor to evaluate the expression safely
    return new Function(`'use strict'; return (${expr})`)();
  }
}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors(); // Enable CORS if needed
  await app.listen(5000);
}
bootstrap();
</CODE>

### Instructions to Run the Application
1. Ensure you have Node.js installed (version >= 20.0.0).
2. Navigate to the project directory.
3. Run `npm install` to install the dependencies.
4. Start the application using `npm run start`.
5. The application will be accessible at `http://0.0.0.0:5000/calculator`.

### Note
- The `calculateExpression` method sanitizes the input to allow only valid arithmetic characters, which mitigates the risks associated with executing arbitrary code.
- The `evaluate` method uses the `Function` constructor to evaluate the sanitized expression, which is safer than using `eval`. However, caution is still advised, and further validation may be necessary for more complex applications.

